/**
 * Whether `actor` may see `project` under the private-project visibility
 * rule. `org` and `public` projects are visible to the whole tenant; a
 * `private` project is visible only to staff, admin/owner roles, its lead,
 * or an explicit project member. Backs `canViewProject()` in
 * `project-service.ts` and the not-found gating every read/write below it
 * relies on.
 */
export async function isProjectVisible(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (actor.role === "admin" || actor.role === "owner") return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** Throws `NotFoundError` in place of a permission error for a hidden project. */
export async function requireProjectVisible(
  actor: Actor,
  project: Project,
): Promise<void> {
  if (!(await isProjectVisible(actor, project))) {
    throw new NotFoundError("Project", project.id);
  }
}

